const d = $input.item.json;
const e = d.enriched || {};
const asOf = String(d.asOf || '').includes('T') ? String(d.asOf).split('T')[1].slice(0,5) : '15:00';
const symbol = e.minute?.symbol || 'sse';
const pts = e.minute?.pts || 0; const close = e.minute?.close || 'NA'; const amt = e.minute?.amt || 0;
const closeBar = e.minute?.hasCloseBar ? 'Y' : 'N'; const amountOk = e.minute?.amountOk ? 'Y' : 'N'; const pctOk = e.minute?.pctOk ? 'Y' : 'N';
let failStep = 'None'; let err = 'None';
if (e.journal?.steps) {
  const failed = e.journal.steps.find(s => s.status === 'failed');
  if (failed) { failStep = failed.name; err = failed.error?.message || (failed.warnings || []).find(w => w.severity === 'error')?.message || 'failed'; }
}
const line1 = `M0-B ❌ day=${d.day} asOf=${asOf} symbol=${symbol}`;
const line2 = `pts=${pts} close=${close} amt=${amt}`;
const line3 = `QA: closeBar=${closeBar} amountOk=${amountOk} pctOk=${pctOk} out: minute2daily + qa (err=${err})`;
return [{ summary: `${line1}\n${line2}\n${line3}` }];

